use crate::SpaceId;

/// A Varnode is the formal triple `(space, offset, size)` that identifies
/// an operand in the IR. Every instruction reads and writes Varnodes.
///
/// Two Varnodes are equal iff all three fields match. Overlapping Varnodes
/// (e.g., `EAX` at `(Register, 0, 4)` and `RAX` at `(Register, 0, 8)`)
/// alias and must be resolved via `SUBPIECE`/`PIECE`/`INDIRECT`.
#[derive(
    Copy, Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, serde::Serialize, serde::Deserialize,
)]
pub struct Varnode {
    pub space: SpaceId,
    pub offset: u64,
    /// Number of contiguous bytes this Varnode covers (1..=16 typical).
    pub size: u8,
}

impl Varnode {
    /// Construct a new Varnode.
    #[inline]
    pub const fn new(space: SpaceId, offset: u64, size: u8) -> Self {
        Self {
            space,
            offset,
            size,
        }
    }

    /// Shorthand for a register-space Varnode.
    #[inline]
    pub const fn reg(offset: u64, size: u8) -> Self {
        Self::new(SpaceId::Register, offset, size)
    }

    /// Shorthand for a constant-space Varnode.
    #[inline]
    pub const fn constant(value: u64, size: u8) -> Self {
        Self::new(SpaceId::Const, value, size)
    }

    /// Shorthand for a unique-space Varnode.
    #[inline]
    pub const fn unique(offset: u64, size: u8) -> Self {
        Self::new(SpaceId::Unique, offset, size)
    }

    /// Shorthand for a stack-space Varnode.
    #[inline]
    pub const fn stack(offset: u64, size: u8) -> Self {
        Self::new(SpaceId::Stack, offset, size)
    }

    /// Shorthand for a RAM-space Varnode.
    #[inline]
    pub const fn ram(offset: u64, size: u8) -> Self {
        Self::new(SpaceId::Ram, offset, size)
    }

    /// Returns the bit-width (`size * 8`).
    #[inline]
    pub const fn bit_width(self) -> u32 {
        (self.size as u32) * 8
    }
}]
[Tool: Bash → //! IR instruction type.

use smallvec::SmallVec;

use crate::{AliasCategory, IrOp, Varnode};

/// A single IR instruction: one opcode applied to Varnode operands.
///
/// An instruction optionally produces an `output` Varnode, reads zero or more
/// `inputs`, and is located at machine address `addr`. When `guard` is set,
/// the instruction executes only if the named architecture condition holds —
/// today this is exclusively populated by the ARM/Thumb lifter for insns
/// inside an `IT` block (cond codes 0..=15, ARM ARM A8.3 encoding).
///
/// For `LOAD`/`STORE` opcodes, `category` may carry an [`AliasCategory`]
/// tag describing the kind of memory accessed. `None` (the default)
/// preserves pre-existing pass behavior — passes treat it as `Unknown`.
/// The tag is purely additive metadata: IR text dumps and golden files
/// are unaffected.
#[derive(Clone, Debug, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct IrInsn {
    pub op: IrOp,
    pub output: Option<Varnode>,
    pub inputs: SmallVec<[Varnode; 3]>,
    /// Machine address this instruction was lifted from.
    pub addr: u64,
    /// Architecture condition code that guards execution, or `None` for
    /// unconditional insns.
    pub guard: Option<u8>,
    /// Optional aliasing / pointer-provenance category for `LOAD`/`STORE`
    /// instructions. `None` means "not categorized"; passes fall back to
    /// their existing conservative behavior. See [`AliasCategory`] for
    /// the barrier semantics applied to `Mmio` / `Volatile`.
    ///
    /// Serialized with a default of `None` so old IR blobs without this
    /// field deserialize cleanly.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub category: Option<AliasCategory>,
}

impl IrInsn {
    /// Construct a new instruction with output.
    pub fn with_output(
        op: IrOp,
        output: Varnode,
        inputs: impl Into<SmallVec<[Varnode; 3]>>,
        addr: u64,
    ) -> Self {
        Self {
            op,
            output: Some(output),
            inputs: inputs.into(),
            addr,
            guard: None,
            category: None,
        }
    }

    /// Construct an instruction without output (e.g. STORE, BRANCH).
    pub fn without_output(op: IrOp, inputs: impl Into<SmallVec<[Varnode; 3]>>, addr: u64) -> Self {
        Self {
            op,
            output: None,
            inputs: inputs.into(),
            addr,
            guard: None,
            category: None,
        }
    }

    /// Returns the alias category, treating `None` as `AliasCategory::Unknown`.
    /// Useful for passes that want a uniform classification without
    /// distinguishing "not yet tagged" from "explicitly unknown".
    pub fn category_or_unknown(&self) -> AliasCategory {
        self.category.unwrap_or(AliasCategory::Unknown)
    }

    /// Builder: attach an [`AliasCategory`] tag. Only meaningful for
    /// `LOAD` and `STORE` opcodes; other ops accept it silently so call
    /// sites don't need a type guard.
    pub fn with_category(mut self, category: AliasCategory) -> Self {
        self.category = Some(category);
        self
    }
}]
[Tool: Bash → //! Address space identifiers for the unlace IR.
//!
//! A [`Varnode`](crate::Varnode) lives in exactly one address space. Five spaces
//! are defined, with stable discriminants matching the IR spec (v1.0 frozen).

/// Identifies the address space a [`Varnode`](crate::Varnode) belongs to.
///
/// Discriminants are part of the stable ABI and must not be reordered
/// (see IR spec v1.0, SS1.1 and SS6).
///
/// | Variant    | Short prefix | Purpose                                  |
/// |------------|--------------|------------------------------------------|
/// | `Register` | `r`          | Architectural registers at fixed offsets. |
/// | `Ram`      | `m`          | Process memory; offset is a VA.          |
/// | `Const`    | `c`          | Immediate constants in the offset field. |
/// | `Unique`   | `u`          | Lifter-private temporaries.              |
/// | `Stack`    | `s`          | Stack-frame slots (signed displacement). |
#[derive(
    Copy, Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, serde::Serialize, serde::Deserialize,
)]
#[non_exhaustive]
#[repr(u8)]
pub enum SpaceId {
    /// Architectural registers (RAX, X0, $a0, ...) at fixed offsets.
    Register = 0,
    /// Process memory; offset is a virtual address.
    Ram = 1,
    /// Immediate constants. The `offset` field holds the constant value.
    Const = 2,
    /// Lifter-private temporaries. Never aliased across instructions.
    Unique = 3,
    /// Stack-frame slots; offset is a signed displacement from frame pointer.
    Stack = 4,
}

impl SpaceId {
    /// Returns the single-character prefix used in the canonical text form.
    #[inline]
    pub const fn prefix(self) -> char {
        match self {
            Self::Register => 'r',
            Self::Ram => 'm',
            Self::Const => 'c',
            Self::Unique => 'u',
            Self::Stack => 's',
        }
    }

    /// Returns the full space name (lowercase).
    #[inline]
    pub const fn name(self) -> &'static str {
        match self {
            Self::Register => "register",
            Self::Ram => "ram",
            Self::Const => "const",
            Self::Unique => "unique",
            Self::Stack => "stack",
        }
    }
}]
