/// Shared, thread-safe session state.
///
/// Wraps internal state in `Arc<RwLock<...>>` so the TUI render thread and
/// the GUI iced runtime can both read concurrently and the CLI/scripts can
/// mutate from a single writer.
#[derive(Clone)]
pub struct Session {
    pub(crate) inner: Arc<RwLock<SessionInner>>,
}

pub(crate) struct SessionInner {
    pub(crate) binary: Option<BinaryImage>,
    pub(crate) binary_path: Option<PathBuf>,
    pub(crate) binary_sha256: Option<[u8; 32]>,
    pub(crate) annotations: Annotations,
    pub(crate) selection: Selection,
    pub(crate) listeners: Vec<Box<dyn Fn(&SessionEvent) + Send + Sync>>,
}

impl Session {
    pub fn new() -> Self {
        Self {
            inner: Arc::new(RwLock::new(SessionInner {
                binary: None,
                binary_path: None,
                binary_sha256: None,
                annotations: Annotations::new(),
                selection: Selection::default(),
                listeners: Vec::new(),
            })),
        }
    }

    /// Load a binary file into the session.
    ///
    /// Dispatches among ELF / PE / Mach-O by magic bytes. Returns an error
    /// if the file format is not recognized.
    pub fn load_binary(&self, path: impl AsRef<Path>) -> anyhow::Result<()> {
        let path = path.as_ref();
        let bytes = std::fs::read(path)?;
        let sha = sha256(&bytes);
        let image = dispatch_loader(&bytes)?;

        {
            let mut g = self.inner.write();
            g.binary = Some(image);
            g.binary_path = Some(path.to_path_buf());
            g.binary_sha256 = Some(sha);
        }
        self.emit(SessionEvent::Loaded {
            path: path.to_path_buf(),
        });
        Ok(())
    }

    pub fn binary_path(&self) -> Option<PathBuf> {
        self.inner.read().binary_path.clone()
    }

    pub fn binary_sha256(&self) -> Option<[u8; 32]> {
        self.inner.read().binary_sha256
    }

    pub fn with_binary<F, R>(&self, f: F) -> Option<R>
    where
        F: FnOnce(&BinaryImage) -> R,
    {
        let g = self.inner.read();
        g.binary.as_ref().map(f)
    }

    pub fn annotations(&self) -> Annotations {
        self.inner.read().annotations.clone()
    }

    pub fn selection(&self) -> Selection {
        self.inner.read().selection
    }

    pub fn set_selection(&self, sel: Selection) {
        {
            let mut g = self.inner.write();
            g.selection = sel;
        }
        self.emit(SessionEvent::SelectionChanged(sel));
    }

    pub fn rename(&self, r: Rename) {
        {
            let mut g = self.inner.write();
            g.annotations.renames.insert(r.ea, r.clone());
        }
        self.emit(SessionEvent::Renamed(r));
    }

    pub fn add_comment(&self, c: Comment) {
        {
            let mut g = self.inner.write();
            g.annotations.comments.insert(c.ea, c.clone());
        }
        self.emit(SessionEvent::Commented(c));
    }

    pub fn set_type(&self, t: TypeAnnotation) {
        {
            let mut g = self.inner.write();
            g.annotations.types.insert(t.ea, t.clone());
        }
        self.emit(SessionEvent::Typed(t));
    }

    pub fn add_bookmark(&self, b: Bookmark) {
        {
            let mut g = self.inner.write();
            g.annotations.bookmarks.insert(b.ea, b.clone());
        }
        self.emit(SessionEvent::Bookmarked(b));
    }

    pub fn add_patch(&self, p: Patch) {
        {
            let mut g = self.inner.write();
            g.annotations.patches.insert(p.ea, p.clone());
        }
        self.emit(SessionEvent::Patched(p));
    }

    /// Subscribe a listener to all session events.
    pub fn subscribe<F>(&self, listener: F)
    where
        F: Fn(&SessionEvent) + Send + Sync + 'static,
    {
        let mut g = self.inner.write();
        g.listeners.push(Box::new(listener));
    }

    fn emit(&self, event: SessionEvent) {
        let g = self.inner.read();
        for listener in &g.listeners {
            listener(&event);
        }
    }
}

impl Default for Session {
    fn default() -> Self {
        Self::new()]
[Tool: Bash → //! Symbol-server URL builders and cache layout.
//!
//! Implements the URL construction rules for the major public symbol
//! servers. The actual HTTP fetch is left to the caller (so this module
//! stays offline-testable and has no async runtime dependency).
//!
//! Supported servers:
//!
//! - Microsoft Symbol Server (PE): `https://msdl.microsoft.com/download/symbols/`
//! - debuginfod (ELF / Linux):    `https://debuginfod.elfutils.org/`
//! - dSYM (Mach-O, local-only):    Spotlight-based, no URL
//!
//! Cache layout:
//! ```text
//! ~/.cache/unlace/symcache/
//!   msft/<pdb-name>/<guid+age>/<pdb-name>
//!   debuginfod/<buildid>/debuginfo
//!   dsym/<uuid>/<bundle.dSYM>
//! ```
//!
//! References:
//! - research/ida-hexrays-docs/changelogs/ida-9_0.txt — IDA 9.0 PDB module
//! - references/ida/plugins/pdb/all/ (1421 fns) — IDA's PDB loader
//! - research/ida-hexrays-docs/changelogs/ida-9_3.txt — debuginfod support

use std::path::PathBuf;

/// Build the Microsoft Symbol Server URL for a given PDB.
///
/// Inputs come from the `RSDS` debug directory in a PE binary:
/// - `pdb_name`: e.g. `kernel32.pdb`
/// - `guid`: the 16-byte GUID from the CodeView record (formatted as
///   `<8>-<4>-<4>-<4>-<12>` lowercase hex, no dashes for the URL)
/// - `age`: the 32-bit age counter
pub fn msft_symbol_server_url(pdb_name: &str, guid: &[u8; 16], age: u32) -> String {
    // MSFT format: GUID is uppercase hex *with* a specific shuffle, then
    // append the age. Reference: docs.microsoft.com/symbol-server.
    let guid_hex = msft_guid_hex(guid);
    let age_hex = format!("{:x}", age);
    format!(
        "https://msdl.microsoft.com/download/symbols/{pdb_name}/{guid_hex}{age_hex}/{pdb_name}"
    )
}

/// Format a 16-byte GUID into MSFT's canonical uppercase no-dash form:
/// - bytes 0..4 little-endian → 8 hex chars
/// - bytes 4..6 little-endian → 4 hex chars
/// - bytes 6..8 little-endian → 4 hex chars
/// - bytes 8..10 big-endian   → 4 hex chars
/// - bytes 10..16 big-endian  → 12 hex chars
pub fn msft_guid_hex(guid: &[u8; 16]) -> String {
    let mut s = String::with_capacity(32);
    // Field 1: 4 bytes little-endian
    for i in (0..4).rev() {
        s.push_str(&format!("{:02X}", guid[i]));
    }
    // Field 2: 2 bytes little-endian
    for i in (4..6).rev() {
        s.push_str(&format!("{:02X}", guid[i]));
    }
    // Field 3: 2 bytes little-endian
    for i in (6..8).rev() {
        s.push_str(&format!("{:02X}", guid[i]));
    }
    // Fields 4 + 5: big-endian
    for byte in &guid[8..16] {
        s.push_str(&format!("{:02X}", byte));
    }
    s
}

/// Build the debuginfod URL for a Linux build-id.
pub fn debuginfod_url(server: &str, buildid: &[u8]) -> String {
    let hex: String = buildid.iter().map(|b| format!("{:02x}", b)).collect();
    let base = server.trim_end_matches('/');
    format!("{base}/buildid/{hex}/debuginfo")
}

/// Build the debuginfod URL for an executable (rather than the debug file).
pub fn debuginfod_executable_url(server: &str, buildid: &[u8]) -> String {
    let hex: String = buildid.iter().map(|b| format!("{:02x}", b)).collect();
    let base = server.trim_end_matches('/');
    format!("{base}/buildid/{hex}/executable")
}

/// Default symbol cache directory: `$HOME/.cache/unlace/symcache/`.
pub fn default_cache_dir() -> PathBuf {
    let home = std::env::var_os("HOME")
        .or_else(|| std::env::var_os("USERPROFILE"))
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("."));
    home.join(".cache").join("unlace").join("symcache")
}

/// Cache key for an MSFT PDB lookup.
pub fn msft_cache_path(cache_dir: &std::path::Path, pdb_name: &str, guid: &[u8; 16], age: u32) -> PathBuf {
    let guid_hex = msft_guid_hex(guid);
    let age_hex = format!("{:x}", age);
    cache_dir
        .join("msft")
        .join(pdb_name)
        .join(format!("{guid_hex}{age_hex}"))
        .join(pdb_name)
}

/// Cache key for a debuginfod lookup.
pub fn debuginfod_cache_path(cache_dir: &std::path::Path, buildid: &[u8]) -> PathBuf {
    let hex: String = buildid.iter().map(|b| format!("{:02x}", b)).collect();
    cache_dir.join("debuginfod").join(&hex).join("debuginfo")
}

/// Configuration values reachable via `unlace config set symcache.*`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SymcacheConfig {
    pub path: PathBuf,
    pub timeout_secs: u64,
    pub servers: Vec<String>,
}

impl Default for SymcacheConfig {
    fn default() -> Self {
        Self {
            path: default_cache_dir(),
            timeout_secs: 30,
            servers: vec![
                "msft".into(),
                "debuginfod".into(),
            ],
        }
    }
}

