42: pub fn run(interp: &mut Interpreter, cfg: &RunConfig) -> RunResult {
43:     // Set up the stack region.
44:     let stack_low = cfg.stack_top.saturating_sub(cfg.stack_size);
45:     let stack_bytes = vec![0u8; cfg.stack_size as usize];
46:     interp
47:         .memory
48:         .map(stack_low, &stack_bytes, (true, true, false));
49:     interp.regs.set("rsp", cfg.stack_top);
50:     interp.regs.set("rbp", cfg.stack_top);
51: 
52:     // Step until termination.
53:     let mut last_outcome = StepOutcome::Continue;
54:     while interp.instruction_count < cfg.max_instructions {
55:         // For the no-op skeleton, we step "in place" and decide we're done
56:         // after one instruction (the host will replace this when the full
57:         // dispatch table lands in B36.2).
58:         last_outcome = interp.step_noop();
59:         if !matches!(last_outcome, StepOutcome::Continue) {
60:             break;
61:         }
62:         // Heuristic: if rip is unset, halt — we have no program loaded.
63:         if interp.regs.get("rip") == 0 && interp.instruction_count > 0 {
64:             last_outcome = StepOutcome::Halt;
65:             break;
66:         }
67:     }
68: 
69:     finalize_result(interp, last_outcome)
