24: /// One PAC-authenticated indirect call site.
25: ///
26: /// Fields mirror the matching [`AuthPointer`] slot: `key` selects the
27: /// PAC key (0=IA, 1=IB, 2=DA, 3=DB) and `diversifier` is the 15-bit
28: /// constant from the v5 chain entry. `use_addr_div` is propagated for
29: /// fidelity but the C printer rendering doesn't currently surface it —
30: /// it would only matter for a verifier that wants to re-sign the slot.
31: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
32: pub struct AuthCallAnnotation {
33:     /// PAC key selector: 0=IA, 1=IB, 2=DA, 3=DB.
34:     pub key: u8,
35:     /// 15-bit constant discriminator.
36:     pub diversifier: u16,
37:     /// Whether the runtime XORs the slot's VA into the discriminator.
38:     pub use_addr_div: bool,
39: }
40: 
41: /// Identify every `Callind` / `Callother` in `func` whose target is
42: /// loaded from an [`AuthPointer`] slot, returning an annotation map
43: /// keyed by `(BlockId, insn_idx)`.
44: ///
45: /// `image_base` is the virtual address of the image's first byte; auth
46: /// pointer offsets are *image-local* (relative to the start of the
47: /// extracted image bytes), so the match-against-LOAD-address rule is
48: /// `load_addr - image_base == auth_pointer.offset`.
49: ///
50: /// When `auth_pointers` is empty the function does no work and returns
51: /// an empty map — this is the fast path for every non-cache image.
52: pub fn resolve_auth_calls(
53:     func: &SsaFunction,
54:     image_base: u64,
55:     auth_pointers: &[AuthPointer],
56: ) -> BTreeMap<(BlockId, usize), AuthCallAnnotation> {
57:     let mut out = BTreeMap::new();
58:     if auth_pointers.is_empty() {
59:         return out;
60:     }
61: 
62:     // Build a `image_local_offset -> AuthPointer` lookup so per-call
63:     // resolution is O(1).
64:     let by_offset: BTreeMap<usize, &AuthPointer> =
65:         auth_pointers.iter().map(|p| (p.offset, p)).collect();
66: 
67:     for (&bid, block) in &func.function.blocks {
68:         for (insn_idx, insn) in block.insns.iter().enumerate() {
69:             if !matches!(insn.op, IrOp::Callind | IrOp::Callother) {
70:                 continue;
71:             }
72:             // Target operand for Callind is inputs[0]; for Callother
73:             // inputs[0] is the intrinsic tag, so we look at inputs[1]
74:             // when present. This keeps the rule "the value being
75:             // *called* is what we care about".
76:             let target_idx = if insn.op == IrOp::Callind { 0 } else { 1 };
77:             let Some(_target_vn) = insn.inputs.get(target_idx) else {
78:                 continue;
79:             };
80: 
81:             // Resolve the LOAD address (if any) that produced this
82:             // target. If the target was loaded from a constant address
83:             // inside an auth slot, we record the annotation.
84:             let Some(&target_sv) =
85:                 func.var_map
86:                     .get(&(bid, insn_idx, VarnodeSlot::Input(target_idx)))
87:             else {
88:                 continue;
89:             };
90:             let Some(load_addr) = trace_load_address(func, target_sv) else {
91:                 continue;
92:             };
93:             let off = match load_addr.checked_sub(image_base) {
94:                 Some(o) => o as usize,
95:                 None => continue,
96:             };
97:             if let Some(ap) = by_offset.get(&off) {
98:                 out.insert(
99:                     (bid, insn_idx),
100:                     AuthCallAnnotation {
101:                         key: ap.key,
102:                         diversifier: ap.diversifier,
103:                         use_addr_div: ap.use_addr_div,
104:                     },
