112: /// Walk back from `sv` through `Copy` and find the first `Load` whose
113: /// address operand is a constant. Returns the constant load address, or
114: /// `None` if the target wasn't produced by a load-from-constant.
115: ///
116: /// We intentionally do *not* follow phi joins or non-constant loads —
117: /// an auth-call annotation must be precise; ambiguity yields no
118: /// annotation rather than a wrong one.
119: fn trace_load_address(func: &SsaFunction, sv: SsaVarnode) -> Option<u64> {
120:     let mut cur = sv;
121:     let mut hops = 0u32;
122:     // Modest bound — chains longer than this are almost certainly the
123:     // wrong call site and we'd rather bail than walk forever.
124:     while hops < 8 {
125:         hops += 1;
126:         let (bid, idx) = find_def(func, cur)?;
127:         let block = func.function.blocks.get(&bid)?;
128:         let insn = block.insns.get(idx)?;
129:         match insn.op {
130:             IrOp::Copy => {
131:                 let inp = insn.inputs.first()?;
132:                 if inp.space == SpaceId::Const {
133:                     // A copy from a constant *is* a direct call target,
134:                     // not a load. Not an auth-call.
135:                     return None;
136:                 }
137:                 cur = *func.var_map.get(&(bid, idx, VarnodeSlot::Input(0)))?;
138:             }
139:             IrOp::Load => {
140:                 // Load is `output = LOAD(space, addr)`. `addr` is inputs[1].
141:                 let addr = insn.inputs.get(1)?;
142:                 if addr.space == SpaceId::Const {
143:                     return Some(addr.offset);
144:                 }
145:                 // Address came from another SSA value — follow it.
146:                 cur = *func.var_map.get(&(bid, idx, VarnodeSlot::Input(1)))?;
147:             }
148:             _ => return None,
149:         }
150:     }
151:     None
152: }
153: 
154: /// Locate the `(BlockId, insn_idx)` whose **output** is `sv`. Phi
155: /// definitions are ignored (only direct instruction outputs are
156: /// considered, mirroring `indirect_call_resolve::find_def`).
157: fn find_def(func: &SsaFunction, sv: SsaVarnode) -> Option<(BlockId, usize)> {
158:     func.var_map.iter().find_map(|((bid, idx, slot), other)| {
159:         if *other == sv && matches!(slot, VarnodeSlot::Output) {
160:             Some((*bid, *idx))
161:         } else {
162:             None
163:         }
164:     })
165: }
