15: //! CALLIND(method, iface.data, ...)
16: //! ```
17: //!
18: //! When earlier stores or copies make `iface.tab` a statically-known itab
19: //! address, this pass resolves the call target to the corresponding decoded
20: //! `GoItab.methods[method_index]` entry. The pass is conservative: ambiguous
21: //! chains, missing itabs, zero method entries, or out-of-range method slots are
22: //! ignored rather than guessed.
23: 
24: use std::collections::{BTreeMap, BTreeSet};
25: 
26: use unlace_ir::ssa::{SsaFunction, SsaVarnode, VarnodeSlot};
27: use unlace_ir::{BlockId, IrInsn, IrOp, SpaceId, Varnode};
28: use unlace_loader::go_types::GoItab;
29: 
30: use crate::pass::{Pass, PassError};
31: 
32: const DEFAULT_PTR_SIZE: u64 = 8;
33: const GO_ITAB_FUN_OFFSET: u64 = 24;
34: 
35: /// A recovered Go interface dispatch site.
36: #[derive(Clone, Debug, PartialEq, Eq)]
37: pub struct GoIfaceCall {
38:     /// CFG block holding the `Callind`.
39:     pub block_id: BlockId,
40:     /// Index of the `Callind` within its block.
41:     pub insn_idx: usize,
42:     /// Static `runtime.itab` VA loaded into the interface value.
43:     pub itab_va: u64,
44:     /// Interface method slot (`fun[index]`) selected by the call.
45:     pub method_index: usize,
46:     /// Concrete implementation address from `runtime.itab.fun[index]`.
47:     pub target: u64,
48:     /// Interface type VA from the itab header.
49:     pub inter_type_va: u64,
50:     /// Concrete type VA from the itab header.
51:     pub concrete_type_va: u64,
52: }
53: 
54: /// Function-local pass variant for tests and callers that already have a
55: /// decoded Go itab table.
56: pub struct GoIfaceDevirtPass<'a> {
57:     itabs: &'a BTreeMap<u64, GoItab>,
58: }
59: 
60: impl<'a> GoIfaceDevirtPass<'a> {
61:     pub fn new(itabs: &'a BTreeMap<u64, GoItab>) -> Self {
62:         Self { itabs }
63:     }
64: }
65: 
66: impl Pass for GoIfaceDevirtPass<'_> {
67:     fn name(&self) -> &str {
68:         "go-iface-devirt"
69:     }
70: 
71:     fn phase(&self) -> crate::pass::PassPhase {
72:         crate::pass::PassPhase::TypeRecovery
73:     }
74: 
75:     fn run(&self, func: &mut SsaFunction) -> Result<bool, PassError> {
76:         let found = resolve_go_iface_calls(func, self.itabs);
77:         if found.is_empty() {
