93: /// Detect Go interface calls whose concrete itab is statically known.
94: pub fn resolve_go_iface_calls(
95:     func: &SsaFunction,
96:     itabs: &BTreeMap<u64, GoItab>,
97: ) -> Vec<GoIfaceCall> {
98:     if itabs.is_empty() {
99:         return Vec::new();
100:     }
101: 
102:     let mut out = Vec::new();
103:     for (&bid, block) in &func.function.blocks {
104:         let insns = &block.insns;
105:         for (insn_idx, insn) in insns.iter().enumerate() {
106:             if insn.op != IrOp::Callind || insn.inputs.is_empty() {
107:                 continue;
108:             }
109:             let Some(call) = try_resolve_call(func, bid, insns, insn_idx, itabs) else {
110:                 continue;
111:             };
112:             out.push(call);
113:         }
114:     }
115:     out
116: }
