118: fn try_resolve_call(
119:     func: &SsaFunction,
120:     bid: BlockId,
121:     insns: &[IrInsn],
122:     callind_idx: usize,
123:     itabs: &BTreeMap<u64, GoItab>,
124: ) -> Option<GoIfaceCall> {
125:     let callind = &insns[callind_idx];
126:     let _target = *callind.inputs.first()?;
127: 
128:     // CALLIND target must be produced by a LOAD from itab.fun[N].
129:     let &target_sv = func
130:         .var_map
131:         .get(&(bid, callind_idx, VarnodeSlot::Input(0)))?;
132:     let mut visited = BTreeSet::new();
133:     let method_load = trace_to_load(func, target_sv, &mut visited)?;
134:     let method_insn = insns.get(method_load.1)?;
135:     let method_addr = load_address(method_insn)?;
136:     let (itab_value, method_offset) = resolve_offset(insns, method_load.1, &method_addr)?;
137:     if method_offset < GO_ITAB_FUN_OFFSET {
138:         return None;
139:     }
140:     let slot_off = method_offset - GO_ITAB_FUN_OFFSET;
141:     if slot_off % DEFAULT_PTR_SIZE != 0 {
142:         return None;
143:     }
144:     let method_index = (slot_off / DEFAULT_PTR_SIZE) as usize;
145: 
146:     // `itab_value` is the first word of the interface. Resolve it to a
147:     // constant itab VA, either through a preceding `iface.tab = const` store
148:     // or a direct copy/constant chain in synthetic IR.
149:     let itab_va = resolve_static_itab(func, bid, insns, method_load.1, itab_value)?;
150:     let itab = itabs.get(&itab_va)?;
151:     let target = *itab.methods.get(method_index)?;
152:     if target == 0 {
153:         return None;
154:     }
155: 
156:     Some(GoIfaceCall {
157:         block_id: bid,
158:         insn_idx: callind_idx,
159:         itab_va,
160:         method_index,
161:         target,
162:         inter_type_va: itab.inter_type_va,
163:         concrete_type_va: itab.concrete_type_va,
164:     })
165: }
