167: fn resolve_static_itab(
168:     func: &SsaFunction,
169:     bid: BlockId,
170:     insns: &[IrInsn],
171:     before: usize,
172:     itab_value: Varnode,
173: ) -> Option<u64> {
174:     if itab_value.space == SpaceId::Const {
175:         return Some(itab_value.offset);
176:     }
177: 
178:     if let Some(&sv) = func.var_map.get(&(bid, before, VarnodeSlot::Input(1))) {
179:         let mut visited = BTreeSet::new();
180:         if let Some(value) = trace_constant_value(func, sv, &mut visited) {
