185:     // The usual shape is `itab_value = LOAD(iface + 0)`. Recover the interface
186:     // storage location and find the most recent dominating store to that same
187:     // slot in this basic block. This covers stack materialisation and the
188:     // common register-temporary form emitted by lifters after copy propagation.
189:     let load_idx = find_def(insns, before, &itab_value)?;
190:     let load = insns.get(load_idx)?;
191:     if load.op != IrOp::Load {
192:         return None;
193:     }
194:     let load_addr = load_address(load)?;
195:     let (iface_base, tab_off) = resolve_offset(insns, load_idx, &load_addr)?;
196:     if tab_off != 0 {
197:         return None;
198:     }
199: 
200:     for sinsn in insns.iter().take(load_idx).rev() {
201:         if sinsn.op != IrOp::Store || sinsn.inputs.len() < 3 {
202:             continue;
203:         }
204:         let store_addr = sinsn.inputs[1];
205:         let (store_base, store_off) = match resolve_offset(insns, load_idx, &store_addr) {
206:             Some(v) => v,
207:             None => continue,
208:         };
209:         if store_base == iface_base && store_off == 0 {
210:             let value = sinsn.inputs[2];
211:             if value.space == SpaceId::Const {
212:                 return Some(value.offset);
213:             }
214:             let sidx = insns.iter().position(|i| std::ptr::eq(i, sinsn))?;
215:             let &sv = func.var_map.get(&(bid, sidx, VarnodeSlot::Input(2)))?;
216:             let mut visited = BTreeSet::new();
217:             return trace_constant_value(func, sv, &mut visited);
218:         }
219:     }
220: 
221:     None
222: }
223: 
224: fn trace_to_load(
225:     func: &SsaFunction,
226:     sv: SsaVarnode,
227:     visited: &mut BTreeSet<SsaVarnode>,
228: ) -> Option<(BlockId, usize)> {
229:     if !visited.insert(sv) {
230:         return None;
231:     }
232:     let def = find_ssa_def(func, sv)?;
233:     let insn = func.function.blocks.get(&def.0)?.insns.get(def.1)?;
234:     match insn.op {
235:         IrOp::Load => Some(def),
236:         IrOp::Copy => {
237:             let next = func.var_map.get(&(def.0, def.1, VarnodeSlot::Input(0)))?;
238:             trace_to_load(func, *next, visited)
239:         }
240:         _ => None,
241:     }
242: }
243: 
244: fn trace_constant_value(
245:     func: &SsaFunction,
246:     sv: SsaVarnode,
247:     visited: &mut BTreeSet<SsaVarnode>,
248: ) -> Option<u64> {
249:     if !visited.insert(sv) {
250:         return None;
251:     }
252:     let def = find_ssa_def(func, sv)?;
253:     let insn = func.function.blocks.get(&def.0)?.insns.get(def.1)?;
254:     match insn.op {
255:         IrOp::Copy | IrOp::Cast => {
256:             let input = insn.inputs.first()?;
257:             if input.space == SpaceId::Const {
258:                 return Some(input.offset);
259:             }
260:             let next = func.var_map.get(&(def.0, def.1, VarnodeSlot::Input(0)))?;
261:             trace_constant_value(func, *next, visited)
262:         }
263:         IrOp::IntAdd => match (insn.inputs.first(), insn.inputs.get(1)) {
264:             (Some(a), Some(b)) if a.space == SpaceId::Const && b.space == SpaceId::Const => {
265:                 Some(a.offset.wrapping_add(b.offset))
266:             }
267:             _ => None,
268:         },
269:         _ => None,
270:     }
271: }
272: 
273: fn load_address(load: &IrInsn) -> Option<Varnode> {
274:     match load.inputs.len() {
275:         1 => Some(load.inputs[0]),
276:         2.. => {
277:             if load.inputs[0].space == SpaceId::Const {
278:                 Some(load.inputs[1])
279:             } else {
280:                 Some(load.inputs[0])
281:             }
282:         }
283:         _ => None,
284:     }
285: }
286: 
287: fn resolve_offset(insns: &[IrInsn], before: usize, vn: &Varnode) -> Option<(Varnode, u64)> {
288:     if vn.space == SpaceId::Const {
289:         return None;
290:     }
291:     if let Some(def_idx) = find_def(insns, before, vn) {
292:         let def = &insns[def_idx];
293:         match def.op {
294:             IrOp::Copy | IrOp::Cast if def.inputs.len() == 1 => {
295:                 return resolve_offset(insns, def_idx, &def.inputs[0]).or(Some((def.inputs[0], 0)));
296:             }
297:             IrOp::IntAdd if def.inputs.len() == 2 => {
298:                 let (a, b) = (def.inputs[0], def.inputs[1]);
299:                 if b.space == SpaceId::Const && a.space != SpaceId::Const {
300:                     return Some((a, b.offset));
301:                 }
302:                 if a.space == SpaceId::Const && b.space != SpaceId::Const {
303:                     return Some((b, a.offset));
304:                 }
305:             }
306:             IrOp::Ptradd if def.inputs.len() >= 2 => {
307:                 let (base, idx) = (def.inputs[0], def.inputs[1]);
308:                 if idx.space == SpaceId::Const && base.space != SpaceId::Const {
309:                     let elem_size =
310:                         if def.inputs.len() >= 3 && def.inputs[2].space == SpaceId::Const {
311:                             def.inputs[2].offset
312:                         } else {
313:                             DEFAULT_PTR_SIZE
314:                         };
315:                     return Some((base, idx.offset.saturating_mul(elem_size)));
316:                 }
317:             }
318:             _ => {}
319:         }
320:     }
321:     Some((*vn, 0))
322: }
323: 
324: fn find_def(insns: &[IrInsn], before: usize, vn: &Varnode) -> Option<usize> {
325:     insns
326:         .iter()
327:         .enumerate()
328:         .take(before)
329:         .rev()
330:         .find_map(|(idx, insn)| (insn.output == Some(*vn)).then_some(idx))
331: }
332: 
333: fn find_ssa_def(func: &SsaFunction, sv: SsaVarnode) -> Option<(BlockId, usize)> {
334:     func.var_map.iter().find_map(|((bid, idx, slot), other)| {
335:         if *other == sv && matches!(slot, VarnodeSlot::Output) {
336:             Some((*bid, *idx))
337:         } else {
338:             None
339:         }
340:     })
341: }
