[Tool: Read → 1: //! Function-pointer resolution for indirect calls.
2: //!
3: //! For every `Callind`, attempt to recover a unique constant target
4: //! address by tracing the SSA chain backwards through `Copy` /
5: //! `Load(addr=const)` / `IntAdd(const, const)` instructions. When the chain
6: //! terminates at a single constant, the call site is recorded in
7: //! [`SsaFunction::resolved_indirect_calls`]; ambiguous (multi-source) targets
8: //! are left untouched so downstream passes can still treat them as opaque.
9: //!
10: //! Mirrors the role of IDA's `apply_tinfo` driver
11: //! (`references/ida/idalib/all/apply_tinfo.c`): once the call target is
12: //! known concretely, the registry-resident signature flows in to refine
13: //! caller-side argument and return-value types.
14: 
15: use std::collections::{BTreeMap, BTreeSet};
16: 
17: use unlace_ir::ssa::{SsaFunction, SsaVarnode, TargetSet, VarnodeSlot};
18: use unlace_ir::{BlockId, IrOp, SpaceId};
19: 
20: use crate::pass::{Pass, PassError};
21: 
22: pub struct IndirectCallResolvePass;
23: 
24: impl Pass for IndirectCallResolvePass {
25:     fn name(&self) -> &str {
26:         "indirect-call-resolve"
27:     }
28: 
29:     fn phase(&self) -> crate::pass::PassPhase {
30:         crate::pass::PassPhase::GlobalOpt
31:     }
32: 
33:     fn run(&self, func: &mut SsaFunction) -> Result<bool, PassError> {
34:         let snapshot = func.resolved_indirect_calls.clone();
35:         let targets_snapshot = func.indirect_call_targets.clone();
36:         let mut found: BTreeMap<(BlockId, usize), u64> = BTreeMap::new();
37:         let mut targets: BTreeMap<(BlockId, usize), TargetSet> = BTreeMap::new();
38: 
39:         for (&bid, block) in &func.function.blocks {
40:             for (insn_idx, insn) in block.insns.iter().enumerate() {
41:                 if insn.op != IrOp::Callind {
42:                     continue;
43:                 }
44:                 let Some(target_vn) = insn.inputs.first() else {
45:                     continue;
46:                 };
47: 
48:                 // Direct constant target in inputs[0] — trivial single hit.
49:                 if target_vn.space == SpaceId::Const {
50:                     let addr = target_vn.offset;
51:                     found.insert((bid, insn_idx), addr);
52:                     targets.insert((bid, insn_idx), resolved_target(addr));
53:                     continue;
54:                 }
55: 
56:                 let Some(&target_sv) = func.var_map.get(&(bid, insn_idx, VarnodeSlot::Input(0)))
57:                 else {
58:                     targets.insert((bid, insn_idx), TargetSet::Unknown);
59:                     continue;
60:                 };
61: 
62:                 // Collect every reachable constant target through Copy
63:                 // chains, Load(const_addr), IntAdd(const, const), and phi
64:                 // joins. The set's cardinality classifies the call:
65:                 //   0 → `Unknown`, 1 → `Resolved`, ≥2 → `Multiple`.
66:                 let mut visited = BTreeSet::new();
67:                 let mut sinks: BTreeSet<u64> = BTreeSet::new();
68:                 gather_constants(func, target_sv, &mut visited, &mut sinks);
69: 
70:                 match sinks.len() {
71:                     0 => {
72:                         targets.insert((bid, insn_idx), TargetSet::Unknown);
73:                     }
74:                     1 => {
75:                         let addr = *sinks.iter().next().unwrap();
76:                         found.insert((bid, insn_idx), addr);
77:                         targets.insert((bid, insn_idx), resolved_target(addr));
78:                     }
79:                     _ => {
80:                         let multi: Vec<(u64, String)> =
81:                             sinks.into_iter().map(|a| (a, name_for(a))).collect();
82:                         targets.insert((bid, insn_idx), TargetSet::Multiple(multi));
83:                     }
84:                 }
85:             }
86:         }
87: 
88:         // Semantic devirtualization entries (`VtableSlot` populated by
89:         // `CppMethodPass`, `ObjcSelector` populated by
90:         // `ObjcDispatchPass`) outrank our constant-tracing classification:
91:         // we only know there's a `LOAD(LOAD(this+0)+N)` chain, the
92:         // language-aware passes know which class/selector it dispatches
93:         // through. Preserve those when they're already recorded so the
94:         // pipeline's second run of this pass (after `CppVtablePass` +
95:         // `CppMethodPass` in the outer fixed point) doesn't downgrade a
96:         // `VtableSlot` to a generic `Unknown`/`Resolved` entry.
97:         for (key, prev) in &targets_snapshot {
98:             if matches!(
99:                 prev,
100:                 TargetSet::VtableSlot { .. } | TargetSet::ObjcSelector(_)
101:             ) {
102:                 targets.insert(*key, prev.clone());
103:             }
104:         }
105: 
106:         let changed = found != snapshot || targets != targets_snapshot;
107:         func.resolved_indirect_calls = found;
108:         func.indirect_call_targets = targets;
109:         Ok(changed)
110:     }
111: }
112: 
113: /// Build a `TargetSet::Resolved` for a single concrete target address.
114: /// Name is the canonical `sub_<addr>` placeholder; the C printer already
115: /// understands this fallback and replaces it with the real symbol name
116: /// when a global resolver is wired in.
117: fn resolved_target(addr: u64) -> TargetSet {
118:     TargetSet::Resolved {
119:         addr,
120:         name: name_for(addr),
121:     }
122: }
123: 
124: fn name_for(addr: u64) -> String {
125:     format!("sub_{:x}", addr)
126: }
127: 
128: /// Phi-aware constant collector for backwards SSA traversal.
129: ///
130: /// Accumulates every constant address reachable through `Copy` / `Load`
131: /// chains, `IntAdd(const, const)`, and phi inputs. Cycles are broken via
132: /// the shared `visited` set; the caller decides whether to map the
133: /// resulting set to `Resolved` (singleton), `Multiple`, or `Unknown`
134: /// (empty).
135: fn gather_constants(
136:     func: &SsaFunction,
137:     sv: SsaVarnode,
138:     visited: &mut BTreeSet<SsaVarnode>,
139:     sinks: &mut BTreeSet<u64>,
140: ) {
141:     if !visited.insert(sv) {
142:         return;
143:     }
144: 
145:     // Phi-defined value: recurse into every incoming SSA varnode.
146:     for phis in func.phi_map.values() {
147:         for phi in phis {
148:             if phi.output == sv {
149:                 for (_, inp) in &phi.inputs {
150:                     gather_constants(func, *inp, visited, sinks);
151:                 }
152:                 return;
153:             }
154:         }
155:     }
156: 
157:     let Some(def_loc) = find_def(func, sv) else {
158:         return;
159:     };
160:     let Some(block) = func.function.blocks.get(&def_loc.0) else {
161:         return;
162:     };
163:     let Some(insn) = block.insns.get(def_loc.1) else {
164:         return;
165:     };
166: 
167:     match insn.op {
168:         IrOp::Copy => {
169:             if let Some(inp) = insn.inputs.first() {
170:                 if inp.space == SpaceId::Const {
171:                     sinks.insert(inp.offset);
172:                     return;
173:                 }
174:             }
175:             if let Some(next) = func
176:                 .var_map
177:                 .get(&(def_loc.0, def_loc.1, VarnodeSlot::Input(0)))
178:                 .copied()
179:             {
180:                 gather_constants(func, next, visited, sinks);
181:             }
182:         }
183:         IrOp::Load => {
184:             if let Some(addr) = insn.inputs.get(1) {
185:                 if addr.space == SpaceId::Const {
186:                     sinks.insert(addr.offset);
187:                 }
188:             }
189:         }
190:         IrOp::IntAdd => {
191:             if let (Some(a), Some(b)) = (insn.inputs.first(), insn.inputs.get(1)) {
192:                 if a.space == SpaceId::Const && b.space == SpaceId::Const {
193:                     sinks.insert(a.offset.wrapping_add(b.offset));
194:                 }
195:             }
196:         }
197:         _ => {}
198:     }
199: }
200: 
201: /// Locate the `(BlockId, insn_index)` whose output is `sv`, by linear
202: /// scan through `var_map`. Phi-defined values are intentionally not
203: /// returned (they imply a multi-source join).
204: fn find_def(func: &SsaFunction, sv: SsaVarnode) -> Option<(BlockId, usize)> {
205:     func.var_map.iter().find_map(|((bid, idx, slot), other)| {
206:         if *other == sv && matches!(slot, VarnodeSlot::Output) {
207:             Some((*bid, *idx))
208:         } else {
209:             None
210:         }
211:     })
212: }
