84: /// An optimization or analysis pass over SSA-form IR.
85: ///
86: /// Passes are stateless: all mutable state lives in the [`SsaFunction`].
87: /// A pass returns `Ok(true)` when it changed the function and `Ok(false)`
88: /// when nothing was modified. The caller iterates to a fixed point.
89: pub trait Pass: Send + Sync {
90:     /// Human-readable name for diagnostics and tracing.
91:     fn name(&self) -> &str;
92: 
93:     /// Which canonical pipeline phase this pass belongs to.
94:     ///
95:     /// Default is [`PassPhase::LocalOpt`] so the trait stays
96:     /// backward-compatible — every concrete pass in the workspace
97:     /// overrides this with its real phase (enforced by the
98:     /// `every_pass_has_explicit_phase` unit test below).
99:     fn phase(&self) -> PassPhase {
100:         PassPhase::LocalOpt
101:     }
102: 
103:     /// Names of passes this one expects to have observed first. The
104:     /// pipeline driver does not currently enforce this; it exists as
105:     /// machine-readable documentation that the test suite can pin and
106:     /// future drivers can consume.
107:     fn depends_on(&self) -> &[&'static str] {
108:         &[]
109:     }
110: 
111:     /// Minimum pipeline maturity required for this pass to run.
112:     ///
113:     /// The pipeline driver skips passes whose `min_maturity()` exceeds
114:     /// the current `SsaFunction::maturity`. Default: derived from
115:     /// [`phase()`](Self::phase) for backward compatibility so existing
116:     /// passes get a correct default without per-file changes.
117:     fn min_maturity(&self) -> unlace_ir::Maturity {
118:         use unlace_ir::Maturity;
119:         match self.phase() {
120:             PassPhase::PreOpt => Maturity::Zero,
121:             PassPhase::LocalOpt => Maturity::Generated,
122:             PassPhase::GlobalOpt => Maturity::PreOptimized,
123:             PassPhase::TypeRecovery => Maturity::LocalOpt,
124:             PassPhase::StackRecovery => Maturity::Generated,
125:             PassPhase::LVarAlloc => Maturity::GlobalOpt,
126:             PassPhase::FinalCleanup => Maturity::Lvars,
127:         }
128:     }
129: 
130:     /// Maximum maturity at which this pass produces useful work.
131:     ///
132:     /// Above this level, the pass is skipped. Default: [`Maturity::Final`]
133:     /// (always runs when `min_maturity` is satisfied).
134:     fn max_maturity(&self) -> unlace_ir::Maturity {
135:         unlace_ir::Maturity::Final
136:     }
137: 
138:     /// Run one iteration of the pass.
139:     ///
140:     /// Returns `Ok(true)` if the function was modified, `Ok(false)` if
141:     /// no changes were made. The caller is responsible for iterating
142:     /// until all passes return `Ok(false)`.
143:     fn run(&self, func: &mut SsaFunction) -> Result<bool, PassError>;
