146: /// Move SSA var-map entries when a block compaction moves an instruction.
147: ///
148: /// Several passes remove instructions and compact `block.insns` in place.
149: /// If the destination index used to belong to a removed instruction, it may
150: /// still have old output/input slots in `var_map`. Clear those destination
151: /// slots before moving the source instruction's slots so stale metadata cannot
152: /// make an output-less instruction look like it defines a variable.
153: pub(crate) fn compact_var_map_for_moved_insn(
154:     var_map: &mut BTreeMap<(BlockId, usize, VarnodeSlot), SsaVarnode>,
155:     bid: BlockId,
156:     old_idx: usize,
157:     new_idx: usize,
158:     input_count: usize,
159: ) {
160:     if new_idx == old_idx {
161:         return;
162:     }
163: 
164:     clear_var_map_entries_at(var_map, bid, new_idx);
165: 
166:     if let Some(sv) = var_map.remove(&(bid, old_idx, VarnodeSlot::Output)) {
167:         var_map.insert((bid, new_idx, VarnodeSlot::Output), sv);
168:     }
169: 
170:     for input_idx in 0..input_count {
171:         if let Some(sv) = var_map.remove(&(bid, old_idx, VarnodeSlot::Input(input_idx))) {
172:             var_map.insert((bid, new_idx, VarnodeSlot::Input(input_idx)), sv);
173:         }
174:     }
175: }
176: 
177: /// Remove every `(bid, idx, *)` entry from `var_map`.
178: ///
179: /// The keys are `(BlockId, usize, VarnodeSlot)` ordered lexicographically,
180: /// so all slots at `(bid, idx)` form a *contiguous range*. Use
181: /// `BTreeMap::extract_if` (stable since 1.91) with a bounded range to do
182: /// one O(log n) descent and drain in place, avoiding the `Vec` and the
183: /// second remove-pass the previous implementation used.
184: ///
185: /// (Measured impact on `/usr/bin/wc`: under the noise floor. The
186: /// `Iter::next` cycles a perf flamegraph attributes to this map come
187: /// almost entirely from reverse lookups in indirect_jump_resolve,
188: /// indirect_call_resolve, auth_call_resolve, and go_iface_devirt —
189: /// each of which scans `var_map.iter()` to find an SsaVarnode by
190: /// value. Fixing those needs a reverse index on SsaFunction and is
191: /// tracked as future work.)
192: fn clear_var_map_entries_at(
193:     var_map: &mut BTreeMap<(BlockId, usize, VarnodeSlot), SsaVarnode>,
194:     bid: BlockId,
195:     idx: usize,
196: ) {
197:     let start = (bid, idx, VarnodeSlot::Output);
198:     let end = (bid, idx, VarnodeSlot::Input(usize::MAX));
199:     var_map.extract_if(start..=end, |_, _| true).for_each(drop);
200: }]
