    var_types: &mut BTreeMap<SsaVarnode, PrimitiveType>,
    sv: SsaVarnode,
    ty: PrimitiveType,
) -> bool {
    let old = var_types
        .get(&sv)
        .copied()
        .unwrap_or(PrimitiveType::Unknown);
    if old != ty {
        var_types.insert(sv, ty);
        true
    } else {
        false
    }
